    {
      "@type": "Question",
      "name": "Are USP and Ph. Eur. grades interchangeable?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. Harmonisation has narrowed the gaps but not closed them. Different pharmacopoeias can specify different analytical methods, different named impurities and different acceptance limits for the same substance."
      }
    },
    {
      "@type": "Question",
      "name": "What is the difference between USP and NF?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "USP covers drug substances and NF covers excipients. A material can be NF grade without being USP grade, and the distinction matters on documentation."
      }
    },
    {
      "@type": "Question",
      "name": "Should I trust a multi-compendial claim?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Verify it. Meeting USP, Ph. Eur., BP and JP simultaneously is achievable when the tightest limit from each is applied, but the claim is easy to make. Ask for a certificate of analysis showing results against each monograph claimed."
      }
    }
  ]
